package com.srm.inventory.service;
import com.srm.inventory.dto.*; import com.srm.inventory.entity.*; import com.srm.inventory.repository.*; import org.junit.jupiter.api.*; import org.mockito.*; import java.math.BigDecimal; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class OrderServiceTest { @Mock OrderRepository orders; @Mock ProductRepository products; @InjectMocks OrderService service; Product product; CustomerOrder order; @BeforeEach void init(){MockitoAnnotations.openMocks(this);product=new Product();product.setId(1L);product.setName("Masala Chips");product.setPrice(new BigDecimal("45"));product.setStockQuantity(4);order=new CustomerOrder();OrderItem item=new OrderItem();item.setProduct(product);item.setQuantity(2);item.setOrder(order);order.getItems().add(item);} @Test void deductsStockWhenPaymentIsApprovedAndOrderIsConfirmed(){order.setPaymentStatus(PaymentStatus.PAYMENT_VERIFIED);when(orders.findById(1L)).thenReturn(Optional.of(order));when(orders.save(any())).thenAnswer(x->x.getArgument(0));var result=service.updateStatus(1L,new StatusRequest(OrderStatus.CONFIRMED));assertEquals(2,product.getStockQuantity());assertEquals(OrderStatus.CONFIRMED,result.getStatus());} @Test void refusesConfirmationBeforePaymentApproval(){order.setPaymentStatus(PaymentStatus.PAYMENT_SUBMITTED);when(orders.findById(1L)).thenReturn(Optional.of(order));assertThrows(IllegalArgumentException.class,()->service.updateStatus(1L,new StatusRequest(OrderStatus.CONFIRMED)));} @Test void restoresStockWhenConfirmedOrderIsCancelled(){order.setStatus(OrderStatus.CONFIRMED);when(orders.findById(1L)).thenReturn(Optional.of(order));when(orders.save(any())).thenAnswer(x->x.getArgument(0));product.setStockQuantity(2);service.updateStatus(1L,new StatusRequest(OrderStatus.CANCELLED));assertEquals(4,product.getStockQuantity());} }
